    @staticmethod
    def near(g, t, dist, dx, dy, tier):
        """Places a fully upgraded tower near a track point offset by (dx, dy)."""
        r = g.get_map().get_routes()[0]
        p = TestKit.buildable_near(g, r.position_at(dist).add(Vec(dx, dy)), 140)
        return TestKit.force_place(g, t, p, tier)
